-- Original FriendsFrame.lua dropdown and tab consumers; no getter/UI replacement.
local function selectRank(index, name)
    ToggleDropDownMenu(1, nil, GuildControlPopupFrameDropDown)
    assert(DropDownList1:IsShown() and DropDownList1.numButtons == 3)
    local button = _G["DropDownList1Button" .. index]
    assert(button:IsShown() and button:GetText() == name)
    button:GetScript("OnClick")(button, "LeftButton")
    assert(UIDropDownMenu_GetSelectedID(GuildControlPopupFrameDropDown) == index)
    assert(GuildControlPopupFrameDropDownText:GetText() == name)
end
local function check(view, deposit, edit, stacks, gold)
    assert(not not GuildControlTabPermissionsViewTab:GetChecked() == view, "view right")
    assert(not not GuildControlTabPermissionsDepositItems:GetChecked() == deposit, "deposit right")
    assert(not not GuildControlTabPermissionsUpdateText:GetChecked() == edit, "edit info right")
    assert(GuildControlWithdrawItemsEditBox:GetText() == tostring(stacks), "stack limit")
    assert(GuildControlWithdrawGoldEditBox:GetText() == tostring(gold), "money limit")
end
ClearPendingGuildBankPermissions()
GuildBankTabPermissionsTab_OnClick(1)
selectRank(2, "Officer")
check(true, false, false, 11, 12)
GuildBankTabPermissionsTab_OnClick(2)
check(true, false, true, 12, 12)
selectRank(3, "Member")
check(false, false, false, 22, 98)
GuildBankTabPermissionsTab_OnClick(1)
check(true, true, true, 21, 98)
selectRank(2, "Officer")
check(true, false, false, 11, 12)
